/* GEOMETOR Codes — Atlas, catalog search, and tab widgets.
 *
 * Data is embedded in each page as <script type="application/json"> blocks
 * generated by geometor.codes.present, so no fetch or path logic is needed.
 */
(function () {
  "use strict";

  function siteRoot() {
    var el = document.documentElement;
    if (el && el.dataset && el.dataset.content_root) return el.dataset.content_root;
    var scripts = document.getElementsByTagName("script");
    for (var i = 0; i < scripts.length; i++) {
      var src = scripts[i].getAttribute("src") || "";
      var k = src.indexOf("_static/codes/codes.js");
      if (k >= 0) return src.slice(0, k);
    }
    return "";
  }

  function h(tag, attrs, children) {
    var el = document.createElement(tag);
    if (attrs) {
      Object.keys(attrs).forEach(function (k) {
        if (k === "text") el.textContent = attrs[k];
        else if (k === "html") el.innerHTML = attrs[k];
        else if (k.slice(0, 2) === "on") el.addEventListener(k.slice(2), attrs[k]);
        else el.setAttribute(k, attrs[k]);
      });
    }
    (children || []).forEach(function (c) {
      if (c == null) return;
      el.appendChild(typeof c === "string" ? document.createTextNode(c) : c);
    });
    return el;
  }

  function readData(id) {
    var node = document.getElementById(id);
    if (!node) return null;
    try {
      return JSON.parse(node.textContent);
    } catch (e) {
      return null;
    }
  }

  /* ------------------------------------------------------------------ Atlas */

  function initAtlas(host) {
    var data = readData(host.getAttribute("data-src"));
    if (!data) return;
    var root = siteRoot();
    var levels = {};
    data.levels.forEach(function (lv) { levels[lv.id] = lv; });
    var state = { mode: "stack", level: null, coreOnly: false, selected: null };

    var controls = h("div", { class: "codes-atlas-controls" });
    var grid = h("div", { class: "codes-atlas-grid" });
    var detail = h("div", { class: "codes-atlas-detail" });
    host.appendChild(controls);
    host.appendChild(grid);
    host.appendChild(detail);

    function chip(label, active, onclick, color) {
      var b = h("button", { class: "codes-chip" + (active ? " active" : ""), type: "button", onclick: onclick, text: label });
      if (color) b.style.setProperty("--chip", color);
      return b;
    }

    function renderControls() {
      controls.innerHTML = "";
      controls.appendChild(chip("Trust Stack", state.mode === "stack", function () { state.mode = "stack"; render(); }));
      controls.appendChild(chip("Comparison axes", state.mode === "axes", function () { state.mode = "axes"; render(); }));
      controls.appendChild(h("span", { class: "codes-sep" }));
      controls.appendChild(chip("All levels", state.level === null, function () { state.level = null; render(); }));
      data.levels.slice().sort(function (a, b) { return a.rank - b.rank; }).forEach(function (lv) {
        if (!data.systems.some(function (s) { return s.ladder === lv.id; })) return;
        controls.appendChild(chip(lv.id + " " + lv.name, state.level === lv.id, function () {
          state.level = state.level === lv.id ? null : lv.id; render();
        }, lv.color));
      });
      controls.appendChild(h("span", { class: "codes-sep" }));
      controls.appendChild(chip("Core only", state.coreOnly, function () { state.coreOnly = !state.coreOnly; render(); }));
    }

    function visibleSystems() {
      return data.systems
        .filter(function (s) { return (!state.level || s.ladder === state.level) && (!state.coreOnly || s.core); })
        .sort(function (a, b) { return levels[b.ladder].rank - levels[a.ladder].rank; });
    }

    function renderGrid() {
      grid.innerHTML = "";
      var cols = state.mode === "stack" ? data.layers : data.axes;
      var table = h("table", { class: "codes-atlas-table" });
      var head = h("tr", null, [h("th", { text: "System" })]);
      cols.forEach(function (c) { head.appendChild(h("th", { text: c.label, title: c.question || "" })); });
      table.appendChild(h("thead", null, [head]));
      var body = h("tbody");
      visibleSystems().forEach(function (s) {
        var lv = levels[s.ladder];
        var tr = h("tr", { class: state.selected === s.id ? "selected" : "" });
        var name = h("td", { class: "codes-atlas-sys" }, [
          h("span", { class: "codes-badge", text: lv.id, title: lv.name + ": " + lv.claim }),
          h("a", { href: root + s.card + ".html", text: s.short }),
        ]);
        name.firstChild.style.background = lv.color;
        tr.appendChild(name);
        cols.forEach(function (c) {
          var txt = (state.mode === "stack" ? s.stack : s.axes)[c.key] || "—";
          tr.appendChild(h("td", { class: "codes-atlas-cell" + (c.key === "checker" ? " checker" : ""), title: txt }, [h("div", { text: txt })]));
        });
        tr.addEventListener("click", function (ev) {
          if (ev.target.tagName === "A") return;
          state.selected = state.selected === s.id ? null : s.id;
          render();
        });
        body.appendChild(tr);
      });
      table.appendChild(body);
      grid.appendChild(table);
    }

    function renderDetail() {
      detail.innerHTML = "";
      if (!state.selected) {
        detail.appendChild(h("p", { class: "codes-hint", text: "Click a row to expand a system; click its name to open the full card." }));
        return;
      }
      var s = data.systems.filter(function (x) { return x.id === state.selected; })[0];
      var lv = levels[s.ladder];
      var trusted = {};
      data.trusted.forEach(function (t) { trusted[t.id] = t; });
      var box = h("div", { class: "codes-detail-box" });
      box.style.borderColor = lv.color;
      box.appendChild(h("h4", null, [h("a", { href: root + s.card + ".html", text: s.name }), " · " + lv.id + " " + lv.name]));
      box.appendChild(h("p", { class: "codes-summary", text: s.summary }));
      var dl = h("dl", { class: "codes-dl" });
      data.layers.forEach(function (l) {
        dl.appendChild(h("dt", { text: l.label, title: l.question }));
        dl.appendChild(h("dd", { text: s.stack[l.key] || "—" }));
      });
      box.appendChild(dl);
      if (s.trusts.length) {
        box.appendChild(h("p", null, [h("strong", { text: "Trusts: " }), s.trusts.map(function (t) {
          return trusted[t] ? trusted[t].name : t;
        }).join(" · ")]));
      }
      if (s.example_code) box.appendChild(h("pre", { class: "codes-example", text: s.example_code }));
      detail.appendChild(box);
    }

    function render() { renderControls(); renderGrid(); renderDetail(); }
    render();
  }

  /* ---------------------------------------------------------------- Catalog */

  function initCatalog(host) {
    var data = readData(host.getAttribute("data-src"));
    if (!data) return;
    var LIMIT = 150;
    var systems = data.systems;
    var state = { q: "", sys: {}, multi: false, family: "" };
    var families = Array.from(new Set(data.principles.map(function (p) { return p.family; }))).sort();
    data.principles.sort(function (a, b) {
      return (b.witness - a.witness) || (b.systems.length - a.systems.length) || a.id.localeCompare(b.id);
    });

    var input = h("input", { type: "search", placeholder: "Search principles, forms, Euclid refs…", class: "codes-search" });
    input.addEventListener("input", function () { state.q = input.value.toLowerCase(); render(); });
    var famSel = h("select", { class: "codes-select" }, [h("option", { value: "", text: "All families" })].concat(
      families.map(function (f) { return h("option", { value: f, text: f }); })));
    famSel.addEventListener("change", function () { state.family = famSel.value; render(); });
    var sysBox = h("div", { class: "codes-atlas-controls" });
    systems.forEach(function (s) {
      var b = h("button", { type: "button", class: "codes-chip", text: s });
      b.addEventListener("click", function () { state.sys[s] = !state.sys[s]; b.classList.toggle("active"); render(); });
      sysBox.appendChild(b);
    });
    var multi = h("button", { type: "button", class: "codes-chip", text: "Multi-system only" });
    multi.addEventListener("click", function () { state.multi = !state.multi; multi.classList.toggle("active"); render(); });
    sysBox.appendChild(h("span", { class: "codes-sep" }));
    sysBox.appendChild(multi);

    var count = h("p", { class: "codes-hint" });
    var out = h("div", { class: "codes-catalog-out" });
    host.appendChild(h("div", { class: "codes-catalog-bar" }, [input, famSel]));
    host.appendChild(sysBox);
    host.appendChild(count);
    host.appendChild(out);

    function matches(p) {
      if (state.family && p.family !== state.family) return false;
      if (state.multi && p.systems.length < 2) return false;
      var need = Object.keys(state.sys).filter(function (k) { return state.sys[k]; });
      for (var i = 0; i < need.length; i++) if (p.systems.indexOf(need[i]) < 0) return false;
      if (!state.q) return true;
      return p.search.indexOf(state.q) >= 0;
    }

    function render() {
      var rows = data.principles.filter(matches);
      count.textContent = rows.length + " of " + data.principles.length + " principles" + (rows.length > LIMIT ? " (showing first " + LIMIT + ")" : "");
      out.innerHTML = "";
      var table = h("table", { class: "codes-atlas-table codes-catalog-table" });
      table.appendChild(h("thead", null, [h("tr", null, [
        h("th", { text: "Principle" }), h("th", { text: "Family" }), h("th", { text: "Systems" }), h("th", { text: "Euclid" }), h("th", { text: "Canonical form" }),
      ])]));
      var body = h("tbody");
      rows.slice(0, LIMIT).forEach(function (p) {
        var name = p.witness
          ? h("a", { href: siteRoot() + "catalog/witnesses/" + p.id + "/index.html", text: p.id })
          : h("code", { text: p.id });
        body.appendChild(h("tr", null, [
          h("td", null, [name, h("div", { class: "codes-sub", text: p.title })]),
          h("td", { text: p.family }),
          h("td", { text: p.systems.join(", ") }),
          h("td", { text: p.euclid.join(", ") }),
          h("td", null, [h("code", { class: "codes-form", text: p.form })]),
        ]));
      });
      table.appendChild(body);
      out.appendChild(table);
    }
    render();
  }

  /* ------------------------------------------------------------------- Tabs */

  function initTabs(host) {
    var panes = Array.prototype.filter.call(host.children, function (c) { return c.classList.contains("codes-tab"); });
    if (!panes.length) return;
    var bar = h("div", { class: "codes-tabbar", role: "tablist" });
    panes.forEach(function (pane, i) {
      var title = pane.getAttribute("data-title");
      var rub = pane.querySelector(".rubric");
      if (!title && rub) title = rub.textContent;
      var status = (pane.className.match(/status-(\w+)/) || [])[1] || "";
      var btn = h("button", { type: "button", class: "codes-tabbtn status-" + status, role: "tab", text: title || "Tab " + (i + 1) });
      btn.addEventListener("click", function () { select(i); });
      bar.appendChild(btn);
    });
    host.insertBefore(bar, host.firstChild);
    host.classList.add("ready");
    function select(k) {
      panes.forEach(function (p, i) { p.style.display = i === k ? "" : "none"; });
      Array.prototype.forEach.call(bar.children, function (b, i) { b.classList.toggle("active", i === k); });
    }
    select(0);
  }

  function boot() {
    document.querySelectorAll(".codes-atlas").forEach(initAtlas);
    document.querySelectorAll(".codes-catalog").forEach(initCatalog);
    document.querySelectorAll(".codes-tabs").forEach(initTabs);
  }

  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", boot);
  else boot();
})();
